		private void QiUpdate()
		{
			if (CurrentBar < 50)
				return;

			// ORIG ordering: UpdateKeyLevels -> UpdateVolumeDelta -> ... -> DetectLiquiditySweeps
			UpdateKeyLevels();
			UpdateVolumeDelta();

			Values[0][0] = 0;
			Values[1][0] = 0;

			DetectLiquiditySweeps();

			DrawDisclaimerOnce();
		}

		// ------------------------------------------------------------------------------
		//  Backtest rule (generated from backtest/rules.yaml - do not edit by hand)
		//  module LiquiditySweep | frame 15m | value sweep_structure = Structure[0] | ORIG lines 2340-2404; note: End events only (ORIG DataBox wrote End events)
		//  long : x == 1
		//  short: x == -1
		// ------------------------------------------------------------------------------
		protected override void OnBarUpdate()
		{
			QiUpdate();
			ApplyRule();
		}

		private void ApplyRule()
		{
			if (BacktestOnly && State == State.Realtime) return;
			if (BarsInProgress != 0) return;

			double x = double.NaN;
			if (Structure.IsValidDataPoint(0))
				x = Structure[0];

			// A NaN / unset value maps to a flat target.
			int target = 0;
			if (!double.IsNaN(x))
			{
				bool goLong  = x == 1.0;
				bool goShort = x == -1.0;
				if (goLong)
					target = 1;
				else if (goShort)
					target = -1;
			}

			if (target == 1 && Position.MarketPosition != MarketPosition.Long)
				EnterLong(DefaultQuantity, "QS_L");
			else if (target == -1 && Position.MarketPosition != MarketPosition.Short)
				EnterShort(DefaultQuantity, "QS_S");
			else if (target == 0)
			{
				if (Position.MarketPosition == MarketPosition.Long)
					ExitLong("QS_XL", "QS_L");
				else if (Position.MarketPosition == MarketPosition.Short)
					ExitShort("QS_XS", "QS_S");
			}
		}

		// ─────────────────────────────────────────────────────────
		//  Volume delta
		// ─────────────────────────────────────────────────────────
		private void UpdateVolumeDelta()
		{
			if (CurrentBar < 1) { volDelta[0] = 0; return; }

			double priceChange = Close[0] - Close[1];
			if (priceChange > 0)
				volDelta[0] = Volume[0];
			else if (priceChange < 0)
				volDelta[0] = -Volume[0];
			else
				volDelta[0] = 0;
		}

		// ─────────────────────────────────────────────────────────
		//  Key Levels: Master dispatcher (tracking only, no drawing)
		// ─────────────────────────────────────────────────────────
		private void UpdateKeyLevels()
		{
			DateTime cstTime = TimeZoneInfo.ConvertTime(Time[0],
				Core.Globals.GeneralOptions.TimeZoneInfo, cstZone);

			if (UsePrevDayLevels)
				UpdatePrevDayHighLow(cstTime);

			if (UseMonthlyLevels)
				UpdateMonthlyHighLow(cstTime);

			if (UseOrbLevels)
				UpdateOrb(cstTime);
		}

		// ─────────────────────────────────────────────────────────
		//  Key Levels: Previous Business Day RTH High/Low
		//  RTH = 8:30 AM – 4:00 PM CST
		//  On weekends, Friday's values persist
		// ─────────────────────────────────────────────────────────
		private void UpdatePrevDayHighLow(DateTime cstTime)
		{
			// Skip weekends — keep Friday's values
			if (cstTime.DayOfWeek == DayOfWeek.Saturday
				|| cstTime.DayOfWeek == DayOfWeek.Sunday)
				return;

			// Detect new trading day (CST date changed)
			if (cstTime.Date != todayRthDate)
			{
				// If we had a valid RTH session, roll it into "previous"
				if (todayRthStarted
					&& todayRthHigh > double.MinValue
					&& todayRthLow < double.MaxValue)
				{
					prevDayHigh = todayRthHigh;
					prevDayLow  = todayRthLow;
					prevDayDate = todayRthDate;
				}

				// Reset today's tracking
				todayRthHigh    = double.MinValue;
				todayRthLow     = double.MaxValue;
				todayRthDate    = cstTime.Date;
				todayRthStarted = false;
			}

			// Check if current bar falls within RTH: 8:30 AM – 4:00 PM CST
			if (IsInRthWindow(cstTime))
			{
				todayRthStarted = true;
				if (High[0] > todayRthHigh) todayRthHigh = High[0];
				if (Low[0]  < todayRthLow)  todayRthLow  = Low[0];
			}
		}

		// ─────────────────────────────────────────────────────────
		//  Key Levels: Current Calendar Month High/Low
		// ─────────────────────────────────────────────────────────
		private void UpdateMonthlyHighLow(DateTime cstTime)
		{
			int barMonth = cstTime.Month;

			// Detect month change — reset
			if (barMonth != klCurrentMonth)
			{
				klMonthlyHigh  = double.MinValue;
				klMonthlyLow   = double.MaxValue;
				klCurrentMonth = barMonth;
			}

			// Always update with current bar
			if (High[0] > klMonthlyHigh) klMonthlyHigh = High[0];
			if (Low[0]  < klMonthlyLow)  klMonthlyLow  = Low[0];
		}

		// ─────────────────────────────────────────────────────────
		//  Key Levels: 30-Min ORB (8:30 – 9:00 AM CST)
		//  On weekends, Friday's ORB values persist
		// ─────────────────────────────────────────────────────────
		private void UpdateOrb(DateTime cstTime)
		{
			// Skip weekends — keep Friday's ORB values
			if (cstTime.DayOfWeek == DayOfWeek.Saturday
				|| cstTime.DayOfWeek == DayOfWeek.Sunday)
				return;

			// Detect new trading day
			if (cstTime.Date != orbDate)
			{
				// If previous day had a completed ORB, archive it
				if (orbComplete
					&& orbHigh > double.MinValue
					&& orbLow < double.MaxValue)
				{
					prevOrbHigh = orbHigh;
					prevOrbLow  = orbLow;
				}

				// Reset for new day
				orbHigh     = double.MinValue;
				orbLow      = double.MaxValue;
				orbComplete = false;
				orbDate     = cstTime.Date;
			}

			// ORB window: 8:30 AM – 9:00 AM CST
			if (IsInOrbWindow(cstTime) && !orbComplete)
			{
				if (High[0] > orbHigh) orbHigh = High[0];
				if (Low[0]  < orbLow)  orbLow  = Low[0];
			}

			// Mark ORB complete once past 9:00 AM CST on the ORB date
			if (!orbComplete && cstTime.Date == orbDate)
			{
				TimeSpan t = cstTime.TimeOfDay;
				if (t >= new TimeSpan(9, 0, 0) && orbHigh > double.MinValue)
				{
					orbComplete = true;
				}
			}
		}

		// ─────────────────────────────────────────────────────────
		//  Key Levels: Time window helpers
		// ─────────────────────────────────────────────────────────
		private bool IsInRthWindow(DateTime cstTime)
		{
			// RTH: 8:30 AM CST (inclusive) to 4:00 PM CST (exclusive)
			TimeSpan t = cstTime.TimeOfDay;
			return t >= new TimeSpan(8, 30, 0) && t < new TimeSpan(16, 0, 0);
		}

		private bool IsInOrbWindow(DateTime cstTime)
		{
			// ORB: 8:30 AM CST (inclusive) to 9:00 AM CST (exclusive)
			TimeSpan t = cstTime.TimeOfDay;
			return t >= new TimeSpan(8, 30, 0) && t < new TimeSpan(9, 0, 0);
		}

		// ─────────────────────────────────────────────────────────
		//  Liquidity Sweep Detection (7 pattern checks)
		// ─────────────────────────────────────────────────────────
		private void DetectLiquiditySweeps()
		{
			if (CurrentBar < SwingLookback * 2 + 5) return;
			barsSinceLastSweep++;

			UpdateSwingPoints();
			UpdateConsolidationZone();
			UpdateDonchianChannel();
			CheckPendingSweepConfirmation();

			var results = new List<string>();
			double totalConf = 0;
			int sweepDir = 0;
			double sweptLevel = 0;

			int d1=0; double c1=0,lv1=0; string n1="";
			if (CheckBasicLiquiditySweep(ref d1,ref c1,ref lv1,ref n1))
			{ sweepDir=d1; totalConf+=c1; sweptLevel=lv1; results.Add(n1); }

			int d2=0; double c2=0,lv2=0; string n2="";
			if (CheckSwingFailurePattern(ref d2,ref c2,ref lv2,ref n2))
			{ if(sweepDir==0) sweepDir=d2; totalConf+=c2; if(sweptLevel==0) sweptLevel=lv2; results.Add(n2); }

			int d3=0; double c3=0,lv3=0; string n3="";
			if (CheckEqualLevelTrap(ref d3,ref c3,ref lv3,ref n3))
			{ if(sweepDir==0) sweepDir=d3; totalConf+=c3; if(sweptLevel==0) sweptLevel=lv3; results.Add(n3); }

			int d4=0; double c4=0,lv4=0; string n4="";
			if (CheckConsolidationBreakoutTrap(ref d4,ref c4,ref lv4,ref n4))
			{ if(sweepDir==0) sweepDir=d4; totalConf+=c4; if(sweptLevel==0) sweptLevel=lv4; results.Add(n4); }

			int d5=0; double c5=0,lv5=0; string n5="";
			if (CheckWyckoffSpringUpthrust(ref d5,ref c5,ref lv5,ref n5))
			{ if(sweepDir==0) sweepDir=d5; totalConf+=c5; if(sweptLevel==0) sweptLevel=lv5; results.Add(n5); }

			int d6=0; double c6=0,lv6=0; string n6="";
			if (CheckTurtleSoup(ref d6,ref c6,ref lv6,ref n6))
			{ if(sweepDir==0) sweepDir=d6; totalConf+=c6; if(sweptLevel==0) sweptLevel=lv6; results.Add(n6); }

			int d7=0; double c7=0,lv7=0; string n7="";
			if (CheckVolumeDivergenceFakeout(ref d7,ref c7,ref lv7,ref n7))
			{ if(sweepDir==0) sweepDir=d7; totalConf+=c7; if(sweptLevel==0) sweptLevel=lv7; results.Add(n7); }

			if (results.Count == 0 || sweepDir == 0) return;
			if (sweepDir == lastSweepDir && barsSinceLastSweep < DuplicateBarWindow) return;

			totalConf = Math.Min(totalConf, 1.0);
			DrawSweepLabel(sweepDir, totalConf, results, sweptLevel, false);
			lastSweepDir = sweepDir;
			barsSinceLastSweep = 0;
		}

		private void UpdateSwingPoints()
		{
			swingHighSeries[0] = double.NaN;
			swingLowSeries[0]  = double.NaN;
			int lb = SwingLookback;
			if (CurrentBar < lb * 2) return;

			double candidateHigh = High[lb];
			bool isSwingHigh = true;
			for (int i = 0; i <= lb * 2; i++)
			{ if (i == lb) continue; if (High[i] > candidateHigh) { isSwingHigh = false; break; } }
			if (isSwingHigh)
			{
				swingHighSeries[lb] = candidateHigh;
				if (lastSwingHigh > double.MinValue
					&& Math.Abs(candidateHigh - lastSwingHigh) < EqualLevelTolerance * 0.01 * candidateHigh)
				{
					double avgLvl = (candidateHigh + lastSwingHigh) / 2.0;
					if (eqPoolPrice.Count >= 10) { eqPoolPrice.RemoveAt(0); eqPoolBar.RemoveAt(0); eqPoolIsHigh.RemoveAt(0); }
					eqPoolPrice.Add(avgLvl); eqPoolBar.Add(CurrentBar); eqPoolIsHigh.Add(true);
				}
				prevSwingHigh = lastSwingHigh; prevSwingHighBar = lastSwingHighBar;
				lastSwingHigh = candidateHigh; lastSwingHighBar = CurrentBar - lb;
			}

			double candidateLow = Low[lb];
			bool isSwingLow = true;
			for (int i = 0; i <= lb * 2; i++)
			{ if (i == lb) continue; if (Low[i] < candidateLow) { isSwingLow = false; break; } }
			if (isSwingLow)
			{
				swingLowSeries[lb] = candidateLow;
				if (lastSwingLow < double.MaxValue
					&& Math.Abs(candidateLow - lastSwingLow) < EqualLevelTolerance * 0.01 * candidateLow)
				{
					double avgLvl = (candidateLow + lastSwingLow) / 2.0;
					if (eqPoolPrice.Count >= 10) { eqPoolPrice.RemoveAt(0); eqPoolBar.RemoveAt(0); eqPoolIsHigh.RemoveAt(0); }
					eqPoolPrice.Add(avgLvl); eqPoolBar.Add(CurrentBar); eqPoolIsHigh.Add(false);
				}
				prevSwingLow = lastSwingLow; prevSwingLowBar = lastSwingLowBar;
				lastSwingLow = candidateLow; lastSwingLowBar = CurrentBar - lb;
			}

			for (int i = eqPoolPrice.Count - 1; i >= 0; i--)
			{ if (CurrentBar - eqPoolBar[i] > 200) { eqPoolPrice.RemoveAt(i); eqPoolBar.RemoveAt(i); eqPoolIsHigh.RemoveAt(i); } }
		}

		private void UpdateConsolidationZone()
		{
			if (CurrentBar < 50 || atrSma50[0] <= 0) return;
			double atrRatio = atr14[0] / atrSma50[0];
			if (atrRatio < ConsolidationAtrRatio)
			{
				if (!isInConsolidation)
				{ isInConsolidation = true; consolidationStartBar = CurrentBar; consolidationHigh = High[0]; consolidationLow = Low[0]; }
				else
				{ if (High[0] > consolidationHigh) consolidationHigh = High[0]; if (Low[0] < consolidationLow) consolidationLow = Low[0]; }
			}
			else if (atrRatio >= ConsolidationAtrRatio * 1.5 && CurrentBar - consolidationStartBar > 50)
				isInConsolidation = false;
		}

		private void UpdateDonchianChannel()
		{
			donchianHigh = double.MinValue; donchianLow = double.MaxValue;
			int limit = Math.Min(SwingLookback, CurrentBar);
			for (int i = 1; i <= limit; i++)
			{ if (High[i] > donchianHigh) donchianHigh = High[i]; if (Low[i] < donchianLow) donchianLow = Low[i]; }
		}

		private void CheckPendingSweepConfirmation()
		{
			if (pendingSweepDir == 0) return;
			if (CurrentBar - pendingSweepBar > pendingSweepConfirmWindow) { pendingSweepDir = 0; return; }
			bool confirmed = (pendingSweepDir == 1 && Close[0] > pendingSweepLevel)
				|| (pendingSweepDir == -1 && Close[0] < pendingSweepLevel);
			if (confirmed)
			{
				var r = new List<string> { pendingSweepType };
				DrawSweepLabel(pendingSweepDir, 0.55, r, pendingSweepLevel, false);
				lastSweepDir = pendingSweepDir; barsSinceLastSweep = 0; pendingSweepDir = 0;
			}
		}

		private bool CheckBasicLiquiditySweep(ref int dir, ref double conf, ref double level, ref string name)
		{
			double body = Math.Abs(Close[0] - Open[0]);
			double upperWick = High[0] - Math.Max(Open[0], Close[0]);
			double lowerWick = Math.Min(Open[0], Close[0]) - Low[0];
			bool volSpike = volSma20[0] > 0 && Volume[0] > SweepVolMultiple * volSma20[0];
			double wickThresh = body > 0 ? SweepWickMultiple : 1.0;

			if (lastSwingHigh > double.MinValue && High[0] > lastSwingHigh && Close[0] < lastSwingHigh)
			{ double wr = body > 0 ? upperWick / body : (upperWick > 0 ? 99 : 0);
			  if (wr >= wickThresh && volSpike) { dir=-1; conf=0.70; level=lastSwingHigh; name="Liq Sweep"; return true; } }

			if (lastSwingLow < double.MaxValue && Low[0] < lastSwingLow && Close[0] > lastSwingLow)
			{ double wr = body > 0 ? lowerWick / body : (lowerWick > 0 ? 99 : 0);
			  if (wr >= wickThresh && volSpike) { dir=1; conf=0.70; level=lastSwingLow; name="Liq Sweep"; return true; } }

			if (UsePrevDayLevels && prevDayHigh > double.MinValue)
			{
				if (High[0] > prevDayHigh && Close[0] < prevDayHigh && volSpike)
				{ double wr = body > 0 ? upperWick/body : (upperWick>0?99:0);
				  if (wr >= wickThresh) { dir=-1; conf=0.85; level=prevDayHigh; name="Sweep PDH"; return true; } }
				if (Low[0] < prevDayLow && Close[0] > prevDayLow && volSpike)
				{ double wr = body > 0 ? lowerWick/body : (lowerWick>0?99:0);
				  if (wr >= wickThresh) { dir=1; conf=0.85; level=prevDayLow; name="Sweep PDL"; return true; } }
			}
			if (UseOrbLevels && orbComplete && orbHigh > double.MinValue)
			{
				if (High[0] > orbHigh && Close[0] < orbHigh && volSpike)
				{ double wr = body > 0 ? upperWick/body : (upperWick>0?99:0);
				  if (wr >= wickThresh) { dir=-1; conf=0.85; level=orbHigh; name="Sweep ORB-H"; return true; } }
				if (Low[0] < orbLow && Close[0] > orbLow && volSpike)
				{ double wr = body > 0 ? lowerWick/body : (lowerWick>0?99:0);
				  if (wr >= wickThresh) { dir=1; conf=0.85; level=orbLow; name="Sweep ORB-L"; return true; } }
			}
			if (UseMonthlyLevels && klMonthlyHigh > double.MinValue)
			{
				if (High[0] > klMonthlyHigh && Close[0] < klMonthlyHigh && volSpike)
				{ double wr = body > 0 ? upperWick/body : (upperWick>0?99:0);
				  if (wr >= wickThresh) { dir=-1; conf=0.85; level=klMonthlyHigh; name="Sweep MoHigh"; return true; } }
				if (Low[0] < klMonthlyLow && Close[0] > klMonthlyLow && volSpike)
				{ double wr = body > 0 ? lowerWick/body : (lowerWick>0?99:0);
				  if (wr >= wickThresh) { dir=1; conf=0.85; level=klMonthlyLow; name="Sweep MoLow"; return true; } }
			}
			return false;
		}

		private bool CheckSwingFailurePattern(ref int dir, ref double conf, ref double level, ref string name)
		{
			if (lastSwingHigh > double.MinValue && High[0] > lastSwingHigh && Close[0] < lastSwingHigh)
			{ dir=-1; conf=0.50; level=lastSwingHigh; name="SFP"; return true; }
			if (lastSwingLow < double.MaxValue && Low[0] < lastSwingLow && Close[0] > lastSwingLow)
			{ dir=1; conf=0.50; level=lastSwingLow; name="SFP"; return true; }
			if (CurrentBar >= 2 && lastSwingHigh > double.MinValue
				&& High[1] > lastSwingHigh && Close[1] > lastSwingHigh && Close[0] < lastSwingHigh)
			{ dir=-1; conf=0.60; level=lastSwingHigh; name="SFP(2bar)"; return true; }
			if (CurrentBar >= 2 && lastSwingLow < double.MaxValue
				&& Low[1] < lastSwingLow && Close[1] < lastSwingLow && Close[0] > lastSwingLow)
			{ dir=1; conf=0.60; level=lastSwingLow; name="SFP(2bar)"; return true; }
			return false;
		}

		private bool CheckEqualLevelTrap(ref int dir, ref double conf, ref double level, ref string name)
		{
			for (int i = eqPoolPrice.Count - 1; i >= 0; i--)
			{
				double lvl = eqPoolPrice[i]; bool isHigh = eqPoolIsHigh[i];
				if (isHigh && High[0] > lvl && Close[0] < lvl)
				{ dir=-1; conf=0.60; level=lvl; name="EqHigh Trap";
				  eqPoolPrice.RemoveAt(i); eqPoolBar.RemoveAt(i); eqPoolIsHigh.RemoveAt(i); return true; }
				if (!isHigh && Low[0] < lvl && Close[0] > lvl)
				{ dir=1; conf=0.60; level=lvl; name="EqLow Trap";
				  eqPoolPrice.RemoveAt(i); eqPoolBar.RemoveAt(i); eqPoolIsHigh.RemoveAt(i); return true; }
			}
			return false;
		}

		private bool CheckConsolidationBreakoutTrap(ref int dir, ref double conf, ref double level, ref string name)
		{
			if (!isInConsolidation && CurrentBar - consolidationStartBar > 10) return false;
			if (consolidationHigh <= consolidationLow) return false;
			bool bigVol = volSma20[0] > 0 && Volume[0] > 2.0 * volSma20[0];
			if (!bigVol) return false;
			if (High[0] > consolidationHigh && Close[0] <= consolidationHigh)
			{ dir=-1; conf=0.65; level=consolidationHigh; name="Consol Trap"; return true; }
			if (Low[0] < consolidationLow && Close[0] >= consolidationLow)
			{ dir=1; conf=0.65; level=consolidationLow; name="Consol Trap"; return true; }
			return false;
		}

		private bool CheckWyckoffSpringUpthrust(ref int dir, ref double conf, ref double level, ref string name)
		{
			int rangeLen = SwingLookback * 2;
			if (CurrentBar < rangeLen + 1) return false;
			double rangeHigh = double.MinValue, rangeLow = double.MaxValue;
			for (int i = 1; i <= rangeLen; i++)
			{ if (High[i] > rangeHigh) rangeHigh = High[i]; if (Low[i] < rangeLow) rangeLow = Low[i]; }
			if (rangeHigh <= rangeLow) return false;
			double baseConf = isInConsolidation ? 0.75 : 0.60;
			if (Low[0] < rangeLow && Close[0] > rangeLow && Close[0] > Open[0])
			{ dir=1; conf=baseConf; level=rangeLow; name="Spring"; return true; }
			if (High[0] > rangeHigh && Close[0] < rangeHigh && Close[0] < Open[0])
			{ dir=-1; conf=baseConf; level=rangeHigh; name="Upthrust"; return true; }
			return false;
		}

		private bool CheckTurtleSoup(ref int dir, ref double conf, ref double level, ref string name)
		{
			if (donchianHigh <= double.MinValue || donchianLow >= double.MaxValue) return false;
			if (High[0] > donchianHigh && Close[0] < donchianHigh && Open[0] < donchianHigh)
			{ dir=-1; conf=0.55; level=donchianHigh; name="Turtle Soup"; return true; }
			if (Low[0] < donchianLow && Close[0] > donchianLow && Open[0] > donchianLow)
			{ dir=1; conf=0.55; level=donchianLow; name="Turtle Soup"; return true; }
			return false;
		}

		private bool CheckVolumeDivergenceFakeout(ref int dir, ref double conf, ref double level, ref string name)
		{
			if (pendingSweepDir != 0) return false;
			bool newHigh = lastSwingHigh > double.MinValue && High[0] > lastSwingHigh;
			bool newLow  = lastSwingLow < double.MaxValue && Low[0] < lastSwingLow;
			if (!newHigh && !newLow) return false;
			double body = Math.Abs(Close[0] - Open[0]);
			double range = High[0] - Low[0];
			bool weakVol = volSma20[0] > 0 && Volume[0] < 0.8 * volSma20[0];
			bool absorbedVol = volSma20[0] > 0 && Volume[0] > SweepVolMultiple * volSma20[0]
				&& range > 0 && body < 0.3 * range;
			if (!weakVol && !absorbedVol) return false;
			string pType = weakVol ? "VolDiv (weak)" : "VolDiv (absorbed)";
			if (newHigh)
			{
				pendingSweepBar=CurrentBar; pendingSweepDir=-1; pendingSweepLevel=lastSwingHigh;
				pendingSweepType=pType; pendingSweepConfirmWindow=3;
				DrawSweepLabel(-1, 0.35, new List<string>{pType}, lastSwingHigh, true);
				return false;
			}
			if (newLow)
			{
				pendingSweepBar=CurrentBar; pendingSweepDir=1; pendingSweepLevel=lastSwingLow;
				pendingSweepType=pType; pendingSweepConfirmWindow=3;
				DrawSweepLabel(1, 0.35, new List<string>{pType}, lastSwingLow, true);
				return false;
			}
			return false;
		}

		// ─────────────────────────────────────────────────────────
		//  Label: pattern names + confidence only (no direction words)
		// ─────────────────────────────────────────────────────────
		private void DrawSweepLabel(int direction, double confidence, List<string> patterns,
			double sweptLevel, bool isStart)
		{
			string header = isStart ? "Liq Sweep Start" : "Liq Sweep End";
			int confPct = (int)Math.Round(confidence * 100);

			string label = header + ": " + string.Join(" + ", patterns) + " (" + confPct + "%)";

			string tag = (isStart ? "LS_S_" : "LS_E_") + CurrentBar;
			Brush brush = direction == 1 ? SweepBullishBrush : SweepBearishBrush;
			SimpleFont font = new SimpleFont("Arial", SignalFontSize) { Bold = true };
			double anchor = direction == 1 ? Low[0] : High[0];
			int offset = direction == 1 ? -(TextOffsetTicks + 30) : (TextOffsetTicks + 30);
			Draw.Text(this, tag, true, label, 0, anchor, offset,
				brush, font, TextAlignment.Center,
				Brushes.Transparent, Brushes.Transparent, 0);

			// Panel plots: confidence and structure direction for this bar.
			// ORIG (2373-2385) wrote its DataBox value only on End events; Start labels still draw.
			if (!isStart)
			{
				Values[0][0] = confidence;
				Values[1][0] = direction;
			}

			// Connecting line between Start and End
			if (isStart)
			{
				pendingSweepStartBar = CurrentBar;
				pendingSweepStartPrice = anchor;
			}
			else if (pendingSweepStartBar > 0)
			{
				int barsBack = CurrentBar - pendingSweepStartBar;
				Draw.Line(this, "LS_Line_" + CurrentBar, true,
					barsBack, pendingSweepStartPrice, 0, anchor,
					brush, DashStyleHelper.Dash, 2);
				pendingSweepStartBar = 0;
				pendingSweepStartPrice = 0;
			}
		}

		private void DrawDisclaimerOnce()
		{
			if (!ShowDisclaimer || disclaimerDrawn)
				return;

			Draw.TextFixed(this, "QI_Disclaimer", "Educational use only - not financial advice",
				TextPosition.BottomLeft, Brushes.Gray, new SimpleFont("Arial", 9),
				Brushes.Transparent, Brushes.Transparent, 0);
			disclaimerDrawn = true;
		}

		public override string DisplayName
		{
			get { return "QS LiquiditySweep"; }
		}

